package services

import "errors"

type Shipment struct {
	Status int // 1: Created, 2: Shipped, 3: Delivered
}

func UpdateStatus(s *Shipment, newStatus int) error {
	// BUG: Missing check to prevent backwards transition
	s.Status = newStatus
	return nil
}

package tests

import (
	"testing"
	"../services"
)

func TestCannotMoveBackwards(t *testing.T) {
	s := &services.Shipment{Status: 3}
	err := services.UpdateStatus(s, 2)
	if err == nil {
		t.Error("Expected error when moving status backwards")
	}
}
